import os
import re
import pytesseract
from PIL import Image
import pandas as pd
from datetime import datetime

def extract_date(text):
    # Regex patterns for various date formats
    patterns = [
        r'(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})',  # DD/MM/YYYY or DD-MM-YYYY
        r'(\d{4})[/-](\d{1,2})[/-](\d{1,2})',  # YYYY/MM/DD or YYYY-MM-DD
        r'(\d{1,2})\s+(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC)[a-z]*\s+(\d{2,4})', # DD MMM YYYY
    ]

    month_map = {
        'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
        'JUL': 7, 'AUG': 8, 'SEP': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12
    }

    for line in text.split('\n'):
        line = line.upper()
        # Try DD/MM/YYYY or DD-MM-YYYY
        match = re.search(r'(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})', line)
        if match:
            d, m, y = match.groups()
            if len(y) == 2:
                y = '20' + y
            try:
                # Could be MM/DD/YYYY or DD/MM/YYYY. Usually DD/MM/YYYY in many regions.
                # If d > 12, it must be DD/MM/YYYY.
                # We'll try DD/MM/YYYY first.
                return datetime(int(y), int(m), int(d)).strftime('%Y-%m-%d')
            except ValueError:
                try:
                    return datetime(int(y), int(d), int(m)).strftime('%Y-%m-%d')
                except ValueError:
                    pass

        # Try YYYY/MM/DD
        match = re.search(r'(\d{4})[/-](\d{1,2})[/-](\d{1,2})', line)
        if match:
            y, m, d = match.groups()
            try:
                return datetime(int(y), int(m), int(d)).strftime('%Y-%m-%d')
            except ValueError:
                pass

        # Try DD MMM YYYY
        match = re.search(r'(\d{1,2})\s+(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC)[A-Z]*\s+(\d{2,4})', line)
        if match:
            d, m_str, y = match.groups()
            m = month_map[m_str[:3]]
            if len(y) == 2:
                y = '20' + y
            try:
                return datetime(int(y), m, int(d)).strftime('%Y-%m-%d')
            except ValueError:
                pass

    return None

def extract_total_amount(text):
    lines = text.split('\n')
    keywords = [
        'GRAND TOTAL',
        'TOTAL RM',
        'TOTAL: RM',
        'TOTAL AMOUNT',
        'TOTAL',
        'AMOUNT',
        'TOTAL DUE',
        'AMOUNT DUE',
        'BALANCE DUE',
        'NETT TOTAL',
        'NET TOTAL'
    ]
    exclusion_keywords = [
        'SUBTOTAL',
        'SUB TOTAL',
        'TAX',
        'GST',
        'SST',
        'DISCOUNT',
        'CHANGE',
        'CASH TENDERED'
    ]

    def find_amount_in_string(s):
        # Look for numbers like 1,234.56 or 1234.56
        # Must have a decimal point and two digits after it for money usually, 
        # but let's be flexible and then format it.
        matches = re.findall(r'(\d{1,3}(?:,\d{3})*\.\d{2})', s)
        if matches:
            return matches[-1].replace(',', '')
        return None

    for i, line in enumerate(lines):
        upper_line = line.upper()

        # Skip if any exclusion keyword is present
        if any(ex in upper_line for ex in exclusion_keywords):
            continue

        for kw in keywords:
            if kw in upper_line:
                # Try to find amount on the same line
                amount = find_amount_in_string(upper_line)
                if amount:
                    return f"{float(amount):.2f}"

                # Fallback: check the next line
                if i + 1 < len(lines):
                    next_line = lines[i+1].upper()
                    # Check if next line has an exclusion keyword? Maybe not necessary for fallback.
                    amount = find_amount_in_string(next_line)
                    if amount:
                        return f"{float(amount):.2f}"
                break # Move to next line if keyword found but no amount

    return None

def process_images(image_dir):
    results = []
    files = sorted([f for f in os.listdir(image_dir) if f.endswith('.jpg')])

    for filename in files:
        path = os.path.join(image_dir, filename)
        try:
            img = Image.open(path)
            # Basic OCR
            text = pytesseract.image_to_string(img)

            date = extract_date(text)
            total_amount = extract_total_amount(text)

            results.append({
                'filename': filename,
                'date': date,
                'total_amount': total_amount
            })
            print(f"Processed {filename}: Date={date}, Amount={total_amount}")
        except Exception as e:
            print(f"Error processing {filename}: {e}")
            results.append({
                'filename': filename,
                'date': None,
                'total_amount': None
            })

    return results

if __name__ == "__main__":
    image_dir = '/app/workspace/dataset/img'
    data = process_images(image_dir)
    df = pd.DataFrame(data)
    df.to_excel('/app/workspace/stat_ocr.xlsx', index=False, sheet_name='results')
    print("Excel file created at /app/workspace/stat_ocr.xlsx")

