import os
import re
import pytesseract
from PIL import Image
from datetime import datetime
from openpyxl import Workbook

def extract_date(text):
    # Regex patterns for various date formats
    # Try to find common date patterns
    patterns = [
        r'(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})',  # DD/MM/YYYY or DD-MM-YYYY
        r'(\d{4})[/-](\d{1,2})[/-](\d{1,2})',  # YYYY/MM/DD or YYYY-MM-DD
    ]

    month_map = {
        'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
        'JUL': 7, 'AUG': 8, 'SEP': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12
    }

    lines = text.split('\n')
    for line in lines:
        line = line.upper().strip()
        if not line:
            continue

        # Try DD MMM YYYY (e.g., 29 JAN 2026)
        match = re.search(r'(\d{1,2})\s+(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC)[A-Z]*\s+(\d{2,4})', line)
        if match:
            d, m_str, y = match.groups()
            m = month_map[m_str[:3]]
            if len(y) == 2:
                y = '20' + y
            try:
                return datetime(int(y), m, int(d)).strftime('%Y-%m-%d')
            except ValueError:
                pass

        # Try DD/MM/YYYY or DD-MM-YYYY
        match = re.search(r'(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})', line)
        if match:
            v1, v2, v3 = match.groups()
            # If v3 is year
            if len(v3) >= 2:
                y = v3 if len(v3) == 4 else '20' + v3
                # Try DD/MM/YYYY
                try:
                    return datetime(int(y), int(v2), int(v1)).strftime('%Y-%m-%d')
                except ValueError:
                    # Try MM/DD/YYYY
                    try:
                        return datetime(int(y), int(v1), int(v2)).strftime('%Y-%m-%d')
                    except ValueError:
                        pass
            # If v1 is year (YYYY/MM/DD)
            if len(v1) == 4:
                try:
                    return datetime(int(v1), int(v2), int(v3)).strftime('%Y-%m-%d')
                except ValueError:
                    pass

    return None

def extract_total_amount(text):
    lines = text.split('\n')
    keywords = [
        'GRAND TOTAL',
        'TOTAL RM',
        'TOTAL: RM',
        'TOTAL AMOUNT',
        'TOTAL',
        'AMOUNT',
        'TOTAL DUE',
        'AMOUNT DUE',
        'BALANCE DUE',
        'NETT TOTAL',
        'NET TOTAL'
    ]
    exclusion_keywords = [
        'SUBTOTAL',
        'SUB TOTAL',
        'TAX',
        'GST',
        'SST',
        'DISCOUNT',
        'CHANGE',
        'CASH TENDERED'
    ]

    def find_amount_in_string(s):
        # Improved regex to handle comma separators and optional currency symbols
        # Matches things like 1,234.56 or 1234.56 or 47.70
        # We look for something that ends with .XX
        matches = re.findall(r'(\d{1,3}(?:,\d{3})*\.\d{2})', s)
        if matches:
            # Return the last one on the line as it's usually the total
            return matches[-1].replace(',', '')
        return None

    for i, line in enumerate(lines):
        upper_line = line.upper()

        # Skip if any exclusion keyword is present
        if any(ex in upper_line for ex in exclusion_keywords):
            continue

        for kw in keywords:
            if kw in upper_line:
                # Try to find amount on the same line after the keyword
                kw_idx = upper_line.find(kw)
                after_kw = upper_line[kw_idx + len(kw):]
                amount = find_amount_in_string(after_kw)
                if amount:
                    return f"{float(amount):.2f}"

                # If not after keyword, try whole line (maybe it's before?)
                amount = find_amount_in_string(upper_line)
                if amount:
                    return f"{float(amount):.2f}"

                # Fallback: check the next line
                if i + 1 < len(lines):
                    next_line = lines[i+1].upper()
                    # But don't pick up exclusion keywords on next line either
                    if any(ex in next_line for ex in exclusion_keywords):
                        continue
                    amount = find_amount_in_string(next_line)
                    if amount:
                        return f"{float(amount):.2f}"
                break # Move to next line if keyword found

    return None

def process_images(image_dir):
    results = []
    files = sorted([f for f in os.listdir(image_dir) if f.endswith('.jpg')])

    for filename in files:
        path = os.path.join(image_dir, filename)
        try:
            img = Image.open(path)
            # Use different PSMs if default fails? 
            # PSM 3 is default. PSM 6 is "Assume a single uniform block of text."
            # PSM 4 is "Assume a single column of text of variable sizes."
            text = pytesseract.image_to_string(img)

            date = extract_date(text)
            total_amount = extract_total_amount(text)

            # If date or amount not found, try with PSM 6
            if not date or not total_amount:
                text_psm6 = pytesseract.image_to_string(img, config='--psm 6')
                if not date: date = extract_date(text_psm6)
                if not total_amount: total_amount = extract_total_amount(text_psm6)

            results.append({
                'filename': filename,
                'date': date,
                'total_amount': total_amount
            })
            print(f"Processed {filename}: Date={date}, Amount={total_amount}")
        except Exception as e:
            print(f"Error processing {filename}: {e}")
            results.append({
                'filename': filename,
                'date': None,
                'total_amount': None
            })

    return results

if __name__ == "__main__":
    image_dir = '/app/workspace/dataset/img'
    data = process_images(image_dir)

    wb = Workbook()
    ws = wb.active
    ws.title = "results"

    ws.append(['filename', 'date', 'total_amount'])
    for item in data:
        ws.append([item['filename'], item['date'], item['total_amount']])

    wb.save('/app/workspace/stat_ocr.xlsx')
    print("Excel file created at /app/workspace/stat_ocr.xlsx")

